/**
 * Checks if the content contains standard Markdown/HTML images 
 * or base64-encoded image strings.
 * * @param {string|object} input - The text or object to check.
 * @returns {object} Analysis result with detection status and matches found.
 */
function checkForImages(input) {
  // Convert object to string if input is JSON/Object
  const textContent = typeof input === 'object' ? JSON.stringify(input) : String(input);

  // 1. Regex for Base64 Data URI images (e.g., data:image/png;base64,...)
  const base64Regex = /data:image\/(?:png|jpg|jpeg|gif|webp|svg\+xml);base64,[A-Za-z0-9+/=]+/gi;

  // 2. Regex for Markdown image syntax (e.g., ![alt](url))
  const markdownImgRegex = /!\[.*?\]\((.*?)\)/g;

  // 3. Regex for HTML <img> tags (e.g., <img src="..." />)
  const htmlImgRegex = /<img\s+[^>]*src=["']?([^"'\s>]+)["']?[^>]*>/gi;

  // Find all matches
  const base64Matches = textContent.match(base64Regex) || [];
  const markdownMatches = textContent.match(markdownImgRegex) || [];
  const htmlMatches = textContent.match(htmlImgRegex) || [];

  const hasBase64 = base64Matches.length > 0;
  const hasImage = hasBase64 || markdownMatches.length > 0 || htmlMatches.length > 0;

  return {
    hasImage: hasImage,
    hasBase64: hasBase64,
    counts: {
      base64Images: base64Matches.length,
      markdownImages: markdownMatches.length,
      htmlImages: htmlMatches.length,
      total: base64Matches.length + markdownMatches.length + htmlMatches.length
    },
    matches: {
      base64: base64Matches,
      markdown: markdownMatches,
      html: htmlMatches
    }
  };
}

// ==========================================
// Integration into n8n JS Node with Reason Logic
// ==========================================
for (const item of $input.all()) {
  const result = checkForImages(item.json);

  item.json.hasImage = result.hasImage;
  item.json.hasBase64 = result.hasBase64;
  item.json.imageDetails = result.counts;

  // If images are detected, append the review flag to any existing Reason text
  if (result.hasImage) {
    const existingReason = item.json.Reason ? String(item.json.Reason).trim() : '';
    const flagText = "NEED MANUAL REVIEW , AS IMAGE";

    if (existingReason.length > 0) {
      item.json.Reason = `${existingReason} | ${flagText}`;
    } else {
      item.json.Reason = flagText;
    }
  }
}

return $input.all();

const MIN_REQUIRED_TOKENS = 200; // Set minimum threshold

const rows = $input.all();

const available = rows
  .map(item => item.json)
  .filter(row => Number(row.TOKEN) >= MIN_REQUIRED_TOKENS)
  .sort((a, b) => Number(b.TOKEN) - Number(a.TOKEN));

if (available.length === 0) {
  throw new Error(`No API keys available with at least ${MIN_REQUIRED_TOKENS} tokens.`);
}

const selected = available[0];

return [{
  json: {
    EMAIL: selected.EMAIL,
    API_KEY: selected.API_KEY,
    TOKEN: Number(selected.TOKEN),
    row_number: selected.row_number
  }
}];

// Access data safely from both upstream extraction branches
const pptItems = $('PPT OUTPUT').all();
const mdItems = $('MD FILE EXTRACTION').all();

// Collect extracted markdown string from PPT extraction (if available)
const pptMarkdown = pptItems.map(item => {
  return item.json.data?.output?.markdown || item.json.markdown || "";
}).filter(Boolean).join("\n\n");

// Collect text content from Markdown extraction (if available)
const markdownText = mdItems.map(item => item.json.data_MD || "").filter(Boolean).join("\n\n");

// Return unified payload for LLM Chain
return [{
  json: {
    data: {
      output: {
        markdown: pptMarkdown
      }
    },
    data_MD: markdownText
  }
}];

const item = $('IF NOT DONE').first().json;

const pptUrl = item["Submit the PPT"];
const mdUrl = item["Submit the MD file"];

function getFileId(url) {
  if (!url) return null;

  // Format: /file/d/FILE_ID/
  let match = url.match(/\/file\/d\/([^/]+)/);
  if (match) return match[1];

  // Format: ?id=FILE_ID or &id=FILE_ID
  match = url.match(/[?&]id=([^&]+)/);
  if (match) return match[1];

  return null;
}

const pptFileId = getFileId(pptUrl);
const mdFileId = getFileId(mdUrl);

if (!pptFileId) {
  throw new Error(`Could not extract PPT file ID from: ${pptUrl}`);
}

if (!mdFileId) {
  throw new Error(`Could not extract MD file ID from: ${mdUrl}`);
}

return [
  {
    json: {
      psId: item["PS ID"],
      teamName: item["Team Name"],
      fileType: "PPT",
      fileId: pptFileId
    }
  },
  {
    json: {
      psId: item["PS ID"],
      teamName: item["Team Name"],
      fileType: "MD",
      fileId: mdFileId
    }
  }
];

const items = $input.all();

return items.map(item => {
  const binary = item.binary?.data;

  if (!binary) {
    return {
      json: {
        ...item.json,
        allowed: false,
        status: "DISQUALIFIED",
        reason: "No file uploaded"
      }
    };
  }

  const fileName = binary.fileName || "";
  const mimeType = (binary.mimeType || "").toLowerCase();

  const extension = fileName.includes(".")
    ? fileName.split(".").pop().toLowerCase()
    : "";

  // Allowed file extensions
  const validExtension =
    extension === "ppt" ||
    extension === "pptx" ||
    extension === "md" ||
    extension === "txt";

  // Allowed MIME types
  const validMime =
    mimeType === "application/vnd.ms-powerpoint" ||
    mimeType === "application/vnd.openxmlformats-officedocument.presentationml.presentation" ||
    mimeType === "text/markdown" ||
    mimeType === "text/plain" ||
    mimeType === "";

  const allowed = validExtension && validMime;

  let fileType;

  if (extension === "ppt" || extension === "pptx") {
    fileType = "PPT";
  } else if (extension === "md" || extension === "txt") {
    fileType = "MARKDOWN";
  } else {
    fileType = "UNKNOWN";
  }

  return {
    json: {
      ...item.json,
      allowed,
      status: allowed ? "ALLOWED" : "DISQUALIFIED",
      fileName,
      fileExtension: extension,
      fileType,
      mimeType,
      reason: allowed
        ? `Valid ${fileType} file`
        : "Only .ppt, .pptx, .md and .txt files are allowed"
    },
    binary: item.binary
  };
});

function extractPSId(value) {
  if (value === null || value === undefined) {
    return {
      id: null,
      reason: "PS ID is missing"
    };
  }

  // Already a number
  if (typeof value === "number") {
    if (
      Number.isFinite(value) &&
      Number.isInteger(value) &&
      value >= 1
    ) {
      return {
        id: value,
        reason: ""
      };
    }

    return {
      id: null,
      reason: "Invalid PS ID number"
    };
  }

  let text = String(value);

  // Normalize whitespace and Unicode characters
  text = text
    .replace(/\u00A0/g, " ")
    .replace(/[\u200B-\u200D\uFEFF]/g, "")
    .replace(/\t/g, " ")
    .replace(/\r?\n/g, " ")
    .replace(/[‐-‒–—―]/g, "-")
    .replace(/\s+/g, " ")
    .trim();

  if (!text) {
    return {
      id: null,
      reason: "PS ID is empty"
    };
  }

  // Pure number as string
  if (/^\d+$/.test(text)) {
    const num = Number(text);

    if (
      Number.isSafeInteger(num) &&
      num >= 1
    ) {
      return {
        id: num,
        reason: ""
      };
    }

    return {
      id: null,
      reason: "Invalid PS ID number"
    };
  }

  // Matches PS_4, PS4, PS_ID:4, PD_ID:5, P_ID:5, PROBLEM_4, etc.
  const match = text.match(
    /\b(?:PS|PD|P|PROBLEM)(?:[\s_-]*ID)?\b\s*(?::|=|-|_)?\s*(?:\(|\[|\{)?\s*(\d+)\s*(?:\)|\]|\})?/i
  );

  if (match) {
    const num = Number(match[1]);

    if (
      Number.isSafeInteger(num) &&
      num >= 1
    ) {
      return {
        id: num,
        reason: ""
      };
    }

    return {
      id: null,
      reason: "Invalid PS ID number"
    };
  }

  // Problem Statement formats (e.g. "Problem Statement 4")
  const problemMatch = text.match(
    /\bproblem[\s_-]*statement\b\s*[:=_-]?\s*(\d+)\b/i
  );

  if (problemMatch) {
    const num = Number(problemMatch[1]);
    const allNumbers = text.match(/\b\d+\b/g) || [];

    if (
      allNumbers.length === 1 &&
      Number.isSafeInteger(num) &&
      num >= 1
    ) {
      return {
        id: num,
        reason: ""
      };
    }

    return {
      id: null,
      reason: "PS ID format contains multiple or ambiguous numbers"
    };
  }

  return {
    id: null,
    reason: `Unable to identify PS ID from submitted value: "${text}"`
  };
}


// =============================================================
// PROCESS ALL INCOMING ITEMS
// =============================================================

return $input.all().map((item) => {
  const originalValue = item.json["PS ID"];
  const result = extractPSId(originalValue);

  // Build output object
  const output = {
    ...item.json,
    "PS ID": result.id
  };

  // Process penalty & reason
  if (result.id === null) {
    // Invalid or unparseable PS ID
    output["Reason"] = item.json["Reason"]
      ? `${item.json["Reason"]}; ${result.reason}`
      : result.reason;
    output["Penality"] = 5;

  } else if (typeof originalValue === "string" && !/^\d+$/.test(originalValue.trim())) {
    // Valid ID extracted, but value was submitted as formatted string (e.g., "PS_4")
    output["Reason"] = originalValue;
    output["Penality"] = 5;

  } else {
    // Clean integer input (number or pure numeric string)
    if (!item.json["Reason"]) {
      output["Reason"] = "";
    }
    if (item.json["Penality"] === undefined) {
      output["Penality"] = "";
    }
  }

  return {
    json: output
  };
});

